import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.util.deparser.SelectDeParser;

import java.io.StringWriter;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    Select pageSelect;
    try {
        Statement stmt = CCJSqlParserUtil.parse(sql);
        if (!(stmt instanceof Select)) {
            throw new PageException("分页语句必须是Select查询!");
        }
        pageSelect = (Select) stmt;
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    PlainSelect plainSelect = (PlainSelect) pageSelect.getSelectBody();
    if (offset != null) {
        plainSelect.setOffset(offset);
    }
    if (limit != null) {
        plainSelect.setLimit(limit);
    }

    StringWriter writer = new StringWriter();
    SelectDeParser deParser = new SelectDeParser(new SelectDeParser(new StringBuilder(writer)));
    pageSelect.getSelectBody().accept(deParser);

    return writer.toString();
}

